import copy
import hashlib
import json
import os
import sys
import tempfile
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import encyclopedia as book


SOURCE = book.NATIVE_TALENT_SOURCE_SHA256


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, ensure_ascii=False,
                                    separators=(",", ":")).encode()).hexdigest()


def fixture():
    # This independent frozen fixture contains all817 bindings, not numeric
    # answers generated by the consumer under test. It is retained locally so
    # these controls also run without a sibling Extractor checkout.
    default = Path(__file__).resolve().parent / "fixtures/native-talent-ids-26297349.json"
    path = Path(os.environ.get("HSE_NATIVE_TALENT_ID_FIXTURE", default))
    contract = json.loads(path.read_text(encoding="utf-8"))
    rows = [{"id": binding["native_id"], "key": binding["key"], "class": binding["class"],
             "effects": [], "id_source": copy.deepcopy(binding)} for binding in contract["record_sources"]]
    contract["grant_domain"] = {"status": "complete_source_bound_grant_lookup",
                                "profile": book.NATIVE_GRANT_DOMAIN_PROFILE,
                                "source_sha256": SOURCE, "stat_id": 202, "lookup": "GetTalentInfo",
                                "lookup_argument_index": 0, "map_variable": "talentStructMap",
                                "same_key_transport_certified": True, "native_consumer_bound": True,
                                "value_transform": "identity", "runtime_value_inferred": False,
                                "level_stat_id": 203, "level_is_separate": True,
                                "level_ranges_certified": False,
                                "proof": {"reference": "reference/native-evidence/item-talent-id-domain-26297349.json",
                                          "sha256": book.NATIVE_GRANT_DOMAIN_REFERENCE_SHA256}}
    return rows, contract


def scalar(value):
    return {"kind": "value", "value": {"kind": "int", "value": value}}


def selector(number, **extra):
    return {"id": 202, "sid": book.GRANTS, "min": number, "status": "decoded",
            "source": {"file": "Hero_Siege.exe", "rva": 123},
            "raw": {"rva": 123, "args": [scalar(202), scalar(number)]}, **extra}


def said(key):
    return {"en": {"talent_name_charge": "Charge", "talent_name_stoneskin": "Stoneskin",
                   "talent_name_blazingTrail": "Blazing Trail"}.get(key, key)}


def grant(stats, rows, contract, tkey="consumable_charge", source=SOURCE):
    talents = book.unique_talent_index(rows, lambda row: row["key"].lower())
    numbers = {row["id"]: row for row in rows}
    spoken = book.unique_talent_index(rows, lambda row: book.flat(said("talent_name_" + row["key"])["en"]))
    native = book.native_talent_context(rows, contract, source)
    # Deliberately misleading key, planner row and anchors must not affect IDs.
    told = {tkey: next(row for row in rows if row["key"] == "charge")}
    return book.granted(tkey, stats, talents, told, numbers, spoken, [(3, 8), (11, 8)], said, native=native)


class NativeTalentGrantTests(unittest.TestCase):
    def test_native_three_is_stoneskin_and_eleven_is_charge_without_offsets(self):
        rows, contract = fixture()
        for number, key in [(3, "stoneskin"), (11, "charge")]:
            stats = [selector(number)]
            original = copy.deepcopy(stats)
            result = grant(stats, rows, contract)
            self.assertEqual((result[0]["talent_id"], result[0]["talent_key"]), (number, key))
            self.assertEqual(result[0]["source_stats"], original)
            self.assertEqual(result[0]["provenance"]["kind"], "decoded")
            self.assertEqual(result[0]["talent_source"]["id_source"], next(row["id_source"] for row in rows if row["id"] == number))
            self.assertEqual(stats, [])

    def test_missing_bad_or_cross_source_contracts_leave_numeric_evidence_raw(self):
        rows, valid = fixture()
        candidates = [None, {}, dict(valid, status="unsupported"), dict(valid, ordinal_fallback=True),
                      dict(valid, native_numeric_map_keys_certified=False), dict(valid, native_contract_id="0" * 64)]
        for field, value in [("stat_id", 203), ("lookup_argument_index", 1), ("value_transform", "offset"),
                             ("same_key_transport_certified", False), ("profile", "unsupported")]:
            changed = copy.deepcopy(valid)
            changed["grant_domain"][field] = value
            candidates.append(changed)
        missing_domain = copy.deepcopy(valid)
        missing_domain.pop("grant_domain")
        candidates.append(missing_domain)
        changed_binding = copy.deepcopy(valid)
        changed_binding["record_sources"][0]["native_id"] = 4
        candidates.append(changed_binding)
        # A self-consistent rewritten certificate is still not the reviewed
        # native proof: recomputing its own hashes must never authorize it.
        forged = copy.deepcopy(valid)
        changed = next(row for row in forged["record_sources"] if row["native_id"] == 3)
        changed["native_id"] = 999999
        changed["binding_sha256"] = digest({key: value for key, value in changed.items() if key != "binding_sha256"})
        forged["record_sources"].sort(key=lambda row: row["native_id"])
        forged["native_contract_id"] = digest({"profile": forged["profile"], "source_sha256": SOURCE,
                                                "witness_sha256": forged["witness"]["sha256"],
                                                "record_sources": forged["record_sources"]})
        candidates.append(forged)
        for contract in candidates:
            stats = [selector(3), {"id": 203, "sid": book.GRANT_LEVELS, "min": 1, "max": 5}]
            before = copy.deepcopy(stats)
            self.assertIsNone(grant(stats, rows, contract))
            self.assertEqual(stats, before)
        self.assertIsNone(grant([selector(3)], rows, valid, source="d" * 64))

    def test_row_proof_mismatch_or_legacy_ordinal_cannot_supply_native_identity(self):
        rows, contract = fixture()
        for mutate in (lambda row: row.pop("id_source"),
                       lambda row: row["id_source"].update(native_id=11),
                       lambda row: row.update(key="charge")):
            changed = copy.deepcopy(rows)
            mutate(next(row for row in changed if row["id"] == 3))
            stats = [selector(3)]
            self.assertIsNone(grant(stats, changed, contract))
            self.assertEqual(stats[0]["min"], 3)
        # The old ordinal was Charge=3. It remains only an explicit legacy
        # inference, whereas the source-bound native key3 above is Stoneskin.
        old = {"id": 3, "key": "charge", "class": "Viking", "effects": []}
        stats = [{"sid": book.GRANTS, "min": 3}]
        legacy = book.granted("consumable_charge", stats, {"charge": old}, {}, {3: old}, {}, [(3, 0)], said)
        self.assertEqual(legacy[0]["names"]["en"], "Charge")
        self.assertEqual(legacy[0]["provenance"]["kind"], "inferred")

    def test_unknown_ranged_partial_and_duplicate_selectors_are_not_consumed(self):
        rows, contract = fixture()
        cases = [[selector(999999)], [selector(3, max=11)], [selector(3, status="partial")],
                 [selector(3, values=[3, None, 11])], [selector(3), selector(11)],
                 [selector(3), selector(3)], [selector(True)], [selector(3, raw={"args": [scalar(202), scalar(11)]})]]
        ranged = selector(3, max=3)
        ranged["raw"]["args"][1] = {"kind": "list", "value": [scalar(3)["value"], scalar(3)["value"]]}
        cases.append([ranged])
        for stats in cases:
            before = copy.deepcopy(stats)
            self.assertIsNone(grant(stats, rows, contract))
            self.assertEqual(stats, before)

    def test_level_holes_and_other_stats_stay_unpaired_and_unchanged(self):
        rows, contract = fixture()
        holes = {"id": 203, "sid": book.GRANT_LEVELS, "values": [None, 1, None, 3],
                 "max": 3, "status": "partial", "raw": {"rva": 124}}
        unrelated = {"id": 201, "sid": "all_talents", "min": 7, "max": 9}
        other_level = {"id": 203, "sid": book.GRANT_LEVELS, "min": 8, "max": 10}
        stats = [selector(11), unrelated, holes, other_level]
        original = copy.deepcopy(stats)
        result = grant(stats, rows, contract)
        self.assertIsNone(result[0]["levels"])
        self.assertEqual(result[0]["source_stats"], original[:1])
        self.assertEqual(stats, original[1:])
        observation = result[0]["level_operand_observations"]
        self.assertFalse(observation["pairing_certified"])
        self.assertEqual(observation["stats"], [holes, other_level])
        self.assertEqual(observation["stats"][0]["values"], [None, 1, None, 3])

    def test_duplicate_keys_and_class_aliases_keep_separate_native_ids(self):
        rows, contract = fixture()
        self.assertNotIn("blazingtrail", book.unique_talent_index(rows, lambda row: row["key"].lower()))
        demon = next(row for row in rows if row["class"] == "DemonSlayer")
        for number, cls in [(20, "Pyromancer"), (663, ""), (demon["id"], "DemonSlayer")]:
            result = grant([selector(number)], rows, contract)
            self.assertEqual(result[0]["talent_id"], number)
            self.assertEqual(result[0]["talent_class"], cls)

    def test_explicit_text_conflict_survives_without_overriding_numeric_identity(self):
        rows, contract = fixture()
        named = selector(3, spell="Charge")
        result = grant([named], rows, contract)
        self.assertEqual([row["talent_key"] for row in result], ["charge", "stoneskin"])
        self.assertTrue(all(row["source_stats"] == [named] for row in result))
        self.assertTrue(all(row["evidence_conflict"]["resolution"] == "independent_evidence_preserved" for row in result))
        self.assertEqual(result[-1]["talent_id"], 3)
        stats = [selector(999999, spell="Charge")]
        result = grant(stats, rows, contract)
        self.assertEqual(result[0]["talent_key"], "charge")
        self.assertEqual(stats[0]["min"], 999999, "independent text must not consume an unknown numeric selector")

    def test_build_current_mode_rejects_missing_proof_instead_of_using_item_key(self):
        old = {"id": 3, "key": "charge", "class": "Viking", "effects": []}
        item = {"metadata": {"tkey": "consumable_charge", "name": "Charge Potion", "record_id": "charge-potion",
                             "fromGame": []}, "stats": [{"id": 202, "sid": book.GRANTS, "min1": 3,
                                                          "status": "decoded", "source": {"file": "Hero_Siege.exe"}}]}
        with tempfile.TemporaryDirectory() as directory:
            csv = Path(directory) / "items.csv"
            csv.write_text("consumable_charge|Charge Potion\n", encoding="utf-8")
            result, *_ = book.build([item], csv, ["en"], {}, str.lower, {}, talent_rows=[old], stat_names={})
        self.assertNotIn("grants", result["consumable_charge"])
        self.assertEqual(result["consumable_charge"]["stats"][0]["min"], 3)


if __name__ == "__main__":
    unittest.main()
